import "dotenv/config";
import { defineConfig } from "@playwright/test";

const PORT = 3100;

/**
 * End-to-end tests drive the production build in a real browser against the `invoicer_test`
 * database. The build goes into its own folder (NEXT_DIST_DIR), so a running dev server is not
 * disturbed.
 */
export default defineConfig({
  testDir: "e2e",
  globalSetup: "./e2e/global-setup.ts",
  // One shared database, so one test at a time.
  fullyParallel: false,
  workers: 1,
  timeout: 60_000,
  expect: { timeout: 10_000 },
  reporter: [["list"]],
  // README screenshots are generated by `npm run screenshots`, not by the normal run.
  grepInvert: process.env.SCREENSHOTS ? undefined : /@screenshots/,
  use: {
    baseURL: `http://localhost:${PORT}`,
    acceptDownloads: true,
    trace: "retain-on-failure",
  },
  webServer: {
    command: `npm run build && npm start -- --port ${PORT}`,
    url: `http://localhost:${PORT}/api/health`,
    timeout: 300_000,
    reuseExistingServer: false,
    env: {
      NEXT_DIST_DIR: ".next-e2e",
      DATABASE_URL: process.env.TEST_DATABASE_URL ?? "",
    },
  },
});
